{
  "status": "partial",
  "claims": [
    {
      "text": "Санкт-Петербургский практический технологический институт был основан 28 ноября (10 декабря) 1828 года по указу императора Николая I.",
      "evidence_ids": [8]
    },
    {
      "text": "Инициатива создания института принадлежала министру финансов Е. Ф. Канкрину.",
      "evidence_ids": [8]
    },
    {
      "text": "Институт был закрытым учебным заведением, где воспитанники набирались из разных губерний преимущественно из сирот и недостаточных больших семейств.",
      "evidence_ids": [9]
    },
    {
      "text": "Санкт-Петербургский государственный университет сервиса и экономики (СПбГУСЭ) ранее существовало как государственное высшее учебное заведение, готовившее специалистов для социальной сферы.",
      "evidence_ids": [100]
    }
  ]
}
